/** Remove only the technical annotations generated by previous data loaders. */
export function cleanBusinessNotes(notes?:string):string|undefined{
 if(!notes)return undefined;
 const generated=[/^Imported from (?:Lead_Tracker_v1\.xlsx|Screenshot \d{4}-\d{2}-\d{2} \d+\.png).*$/,/^Source row \d+:$/,/^Approval refers to modelling approval, not a signed proposal\.$/,/^Contract signature dates are unconfirmed; no Won status inferred\.$/,/^Sales contract value and MRR were not provided; CAPEX is retained separately in Financing\.$/,/^Enquiry received date not recorded; proposal deadline is unavailable until entered\.$/];
 return notes.split(/\r?\n/).filter(line=>!generated.some(pattern=>pattern.test(line.trim()))).join('\n').replace(/\n{3,}/g,'\n\n').trim()||undefined;
}
